  'faq.a4': { fr: 'L’équipe partage les informations pratiques après confirmation de la réservation.', en: 'The team shares practical details after confirming the reservation.', es: 'El equipo comparte los detalles prácticos tras confirmar la reserva.' },
  'faq.q5': { fr: 'Où se déroule la rencontre ?', en: 'Where do meetups take place?', es: '¿Dónde se realizan los encuentros?' },
